import React, {useEffect, useMemo, useRef, useState} from "react";
import {Alert, Button, InputLabel, Stack} from "@mui/material";
import {useNavigate, useParams} from "react-router-dom";
import {toast} from "react-toastify";
import {useForm} from "react-hook-form";
import {yupResolver} from "@hookform/resolvers/yup";
import CoreButton from "../../ui/buttons/coreButton";
import {getApiErrorMessage} from "../../api/errors";
import {FormSurface, MainDiv, PageHeader, PageSubtitle, PageTitle, PageTitleGroup} from "../../ui/commonStyled/commonStyled";
import CoreFormControl from "../../ui/formControl/coreFormControl";
import CoreSelect from "../../ui/select/coreSelect";
import CoreTextField from "../../ui/textFields/coreTextField";
import {useGetLastLevelCategoriesQuery} from "../categories/categoriesApi";
import {CategoryType} from "../../models/category";
import {IProductCharacteristic} from "../../models/product";
import QueryError from "../shared/QueryError";
import Loader from "../../ui/loader/loader";
import CoreFormHelperText from "../../ui/errors/CoreFormHelperText";
import {useCreateProductMutation, useEditProductMutation, useGetProductByIdQuery} from "./productsApi";
import {productSchema} from "./productSchema";
import {useTranslation} from "../../i18n";
import ImageUploadField from "../../ui/fileUpload/ImageUploadField";
import CharacteristicEditor from "../shared/characteristics/CharacteristicEditor";
import CustomFieldEditor, {
    CustomFieldRow,
    customFieldRowsToRecord,
    customFieldsToRows,
    getCustomFieldsValidationError,
} from "../shared/customFields/CustomFieldEditor";

interface Props { isCopy?: boolean; }
interface FormInput { name: string; gtin?: string; description: string; price?: number | null; purchasePrice?: number | null; costPrice?: number | null; markupPercent?: number | null; categoryId: string; }

const CreateOrEditProduct = ({isCopy}: Props) => {
    const {id} = useParams<{id: string}>();
    const navigate = useNavigate();
    const {t} = useTranslation();
    const validationSchema = useMemo(() => productSchema(t), [t]);
    const [imageFile, setImageFile] = useState<File | null>(null);
    const [imagePreview, setImagePreview] = useState("");
    const [characteristics, setCharacteristics] = useState<IProductCharacteristic[]>([]);
    const [characteristicsError, setCharacteristicsError] = useState("");
    const [fields, setFields] = useState<CustomFieldRow[]>([]);
    const [fieldsError, setFieldsError] = useState("");
    const initializedProduct = useRef("");
    const [originalPricing, setOriginalPricing] = useState<{versionId?: string | null; effectiveFrom?: string | null}>({});
    const {setValue, getValues, watch, register, handleSubmit, formState: {errors}} = useForm<FormInput>({
        resolver: yupResolver(validationSchema),
        defaultValues: {name: "", gtin: "", categoryId: "", description: "", price: null, purchasePrice: null, costPrice: null, markupPercent: null},
    });

    const {data: productDetails, isLoading, isError, error, refetch} = useGetProductByIdQuery(id!, {skip: !id});
    const {data: categories, isLoading: isCategoriesLoading, isError: isCategoriesError, error: categoriesError, refetch: refetchCategories} = useGetLastLevelCategoriesQuery({type: CategoryType.Product});

    useEffect(() => {
        if (!productDetails || String(productDetails.id) !== id) return;
        const key = `${id}:${Boolean(isCopy)}`;
        if (initializedProduct.current === key) return;
        initializedProduct.current = key;
        setOriginalPricing({versionId: productDetails.pricingVersionId, effectiveFrom: productDetails.pricingEffectiveFrom});
        setValue("categoryId", String(productDetails.categoryId));
        setValue("name", productDetails.name);
        setValue("gtin", isCopy ? "" : productDetails.gtin ?? "");
        setValue("description", productDetails.description ?? "");
        setValue("price", productDetails.price || null);
        setValue("purchasePrice", productDetails.purchasePrice ?? null);
        setValue("costPrice", productDetails.costPrice ?? null);
        setValue("markupPercent", productDetails.markupPercent ?? null);
        setCharacteristics(productDetails.characteristics ?? []);
        setFields(customFieldsToRows(productDetails.fields));
    }, [id, isCopy, productDetails, setValue]);

    useEffect(() => {
        if (imageFile) {
            const previewUrl = URL.createObjectURL(imageFile);
            setImagePreview(previewUrl);
            return () => URL.revokeObjectURL(previewUrl);
        }
        setImagePreview(productDetails?.imageName ?? "");
    }, [imageFile, productDetails?.imageName]);

    const [createProduct, {isLoading: isCreatingProduct}] = useCreateProductMutation();
    const [editProduct, {isLoading: isEditingProduct}] = useEditProductMutation();
    const isSaving = isCreatingProduct || isEditingProduct;
    const categoryOptions = productDetails && !categories?.some(category => category.id === productDetails.categoryId)
        ? [...(categories ?? []), {id: productDetails.categoryId, name: productDetails.categoryName || `Текущая категория #${productDetails.categoryId}`}]
        : categories;
    const pricingLocked = Boolean(id && !isCopy && originalPricing.versionId);
    const pricingValues = watch(["purchasePrice", "costPrice", "markupPercent", "price"]);
    const missingPrices = ["закупочная цена", "себестоимость", "надбавка", "конечная цена"].filter((_, index) => {
        const value = pricingValues[index];
        return value == null || String(value).trim() === "" || !Number.isFinite(Number(value)) || (index === 2 ? Number(value) < 0 : Number(value) <= 0);
    });

    const validateCharacteristics = () => {
        const names = new Set<string>();
        for (const characteristic of characteristics) {
            const name = characteristic.name.trim();
            if (!name || !characteristic.value.trim()) {
                setCharacteristicsError(t("Characteristic name and value are required."));
                return false;
            }
            const normalizedName = name.toLocaleLowerCase();
            if (names.has(normalizedName)) {
                setCharacteristicsError(t("Characteristic names must be unique."));
                return false;
            }
            names.add(normalizedName);
        }
        setCharacteristicsError("");
        return true;
    };

    const onSubmit = async (values: FormInput) => {
        const customFieldsError = getCustomFieldsValidationError(fields, t);
        setFieldsError(customFieldsError);
        if (!validateCharacteristics() || customFieldsError) return;
        const formData = new FormData();
        formData.append("categoryId", getValues("categoryId"));
        formData.append("name", getValues("name"));
        formData.append("gtin", getValues("gtin") || "");
        if (getValues("description")?.trim()) formData.append("description", getValues("description"));
        for (const key of ["price", "purchasePrice", "costPrice", "markupPercent"] as const) {
            const value = values[key];
            if (value != null) formData.append(key, String(value));
        }
        formData.append("characteristics", JSON.stringify(characteristics));
        formData.append("fields", JSON.stringify(customFieldRowsToRecord(fields)));
        if (imageFile) formData.append("imageFile", imageFile);

        try {
            if (id && !isCopy) {
                formData.append("id", id);
                formData.append("checkPricingVersion", "true");
                if (originalPricing.effectiveFrom) formData.append("expectedPricingEffectiveFrom", originalPricing.effectiveFrom);
                await editProduct(formData).unwrap();
                toast.success(t("Product was changed"));
            } else {
                await createProduct(formData).unwrap();
                toast.success(t("Product was created"));
            }
            navigate("/productsManagement", {replace: true});
        } catch (error) {
            toast.error(getApiErrorMessage(error, t("Product was not saved")));
        }
    };

    if (isCategoriesLoading || isLoading || (id && !isError && String(productDetails?.id) !== id)) return <Loader/>;
    if (id && (isError || !productDetails)) return <MainDiv><QueryError error={error} onRetry={refetch}/></MainDiv>;
    if (isCategoriesError) return <MainDiv><QueryError error={categoriesError} onRetry={refetchCategories}/></MainDiv>;

    return (
        <MainDiv>
            <PageHeader>
                <PageTitleGroup>
                    <PageTitle>{id && !isCopy ? t("Редактирование продукта") : isCopy ? "Копия товара" : t("Новый продукт")}</PageTitle>
                    <PageSubtitle>{t("Product data, image, and arbitrary characteristics.")}</PageSubtitle>
                </PageTitleGroup>
            </PageHeader>
            <FormSurface onSubmit={handleSubmit(onSubmit)}>
                <CoreFormControl verticalMargin>
                    <InputLabel id="product-category-label">{t("Category")}</InputLabel>
                    <CoreSelect
                        labelId="product-category-label"
                        value={watch("categoryId")}
                        onChange={(event: {target: {value: unknown}}) => setValue("categoryId", String(event.target.value), {shouldDirty: true, shouldValidate: true})}
                        disabled={isSaving}
                        register={register}
                        name="categoryId"
                        error={errors.categoryId?.message}
                        label={t("Category")}
                        menuItemProps={categoryOptions}
                    />
                </CoreFormControl>
                {!categoryOptions?.length && <Alert severity="warning">Сначала <a href="#/productCategories" target="_blank" rel="noopener noreferrer">создайте категорию товаров</a>, затем обновите эту страницу.</Alert>}
                {errors.categoryId && <CoreFormHelperText errorMessage={errors.categoryId.message}/>}
                <CoreTextField label={t("Name")} register={register} name="name" error={errors.name?.message} verticalMargin/>
                <CoreTextField label="GTIN" register={register} name="gtin" error={errors.gtin?.message} verticalMargin/>
                <CoreTextField label={t("Description")} register={register} name="description" error={errors.description?.message} verticalMargin/>
                <Alert severity="info">Цены можно заполнить позже. При создании карточки или изменении цен для активации нужны положительные закупочная цена, себестоимость и конечная цена, а также надбавка (допускается 0%). Все цены — в BYN.</Alert>
                {pricingLocked ? <Alert severity="info">Цены утверждены расчётом. Для изменения откройте <a href={`#/costing?mode=receipts&productId=${id}`}>ценообразование</a> или подтвердите новый файл для прихода. Остальные данные карточки можно редактировать.</Alert> : <Alert severity={missingPrices.length ? "warning" : "success"}>{missingPrices.length ? `Не заполнены: ${missingPrices.join(", ")}.` : "Все цены заполнены. После сохранения карточка будет доступна для заказов."}</Alert>}
                <Stack spacing={1}>
                    <CoreTextField type="number" inputProps={{min: 0, step: "any", readOnly: pricingLocked}} label="Конечная цена, BYN (необязательно)" register={register} name="price" error={errors.price?.message} verticalMargin/>
                    <CoreTextField type="number" inputProps={{min: 0, step: "any", readOnly: pricingLocked}} label="Закупочная цена, BYN" register={register} name="purchasePrice" error={errors.purchasePrice?.message} verticalMargin/>
                    <CoreTextField type="number" inputProps={{min: 0, step: "any", readOnly: pricingLocked}} label="Себестоимость, BYN" register={register} name="costPrice" error={errors.costPrice?.message} verticalMargin/>
                    <CoreTextField type="number" inputProps={{min: 0, step: "any", readOnly: pricingLocked}} label="Надбавка, %" register={register} name="markupPercent" error={errors.markupPercent?.message} verticalMargin/>
                </Stack>
                {!pricingLocked && <Button variant="outlined" disabled={isSaving || !(Number(watch("costPrice")) > 0) || watch("markupPercent") == null || String(watch("markupPercent")).trim() === "" || Number(watch("markupPercent")) < 0} onClick={() => setValue("price", Math.round(Number(getValues("costPrice")) * (1 + Number(getValues("markupPercent")) / 100) * 100) / 100, {shouldDirty: true, shouldValidate: true})}>Рассчитать конечную цену из себестоимости и надбавки</Button>}
                <ImageUploadField
                    label={t("Image")}
                    actionText={t("Choose file")}
                    emptyText={t("No file selected")}
                    hint={t("PNG, JPG or WEBP")}
                    fileName={imageFile?.name}
                    previewSrc={imagePreview}
                    previewAlt={getValues("name") || t("Product")}
                    onChange={(event) => setImageFile(event.target.files?.[0] ?? null)}
                />
                <CustomFieldEditor value={fields} onChange={setFields} error={fieldsError}/>
                <CharacteristicEditor
                    title={t("Characteristics")}
                    nameLabel={t("Characteristic name")}
                    valueLabel={t("Value")}
                    addLabel={t("Add characteristic")}
                    removeLabel={t("Remove characteristic")}
                    value={characteristics}
                    onChange={setCharacteristics}
                    error={characteristicsError}
                />
                <CoreButton verticalMargin type="submit" fullWidth muiType="success" disabled={isSaving} text={isSaving ? t("Saving...") : t("Save")}/>
                <CoreButton muiType="secondary" disabled={isSaving} text="Отмена" onClick={() => navigate(id && !isCopy ? `/productsManagement/editProduct/productDetails/${id}` : "/productsManagement")}/>
            </FormSurface>
        </MainDiv>
    );
};

export default CreateOrEditProduct;
