import * as yup from "yup";
import {Translate} from "../../i18n";

export const productSchema = (t: Translate) => yup.object().shape({
    name: yup.string().trim().min(2, "Название должно содержать минимум 2 символа").max(1000, "Название должно содержать не более 1000 символов").required(t("Please fill in this field!")),
    gtin: yup.string()
        .matches(/^(?:\d{8}|\d{12}|\d{13}|\d{14})?$/, t("GTIN must contain 8, 12, 13, or 14 digits.")),
    description: yup.string().ensure(),
    price: yup.number()
        .transform((value, original) => original === "" || original == null ? null : value)
        .nullable()
        .min(0, t("Цена не может быть отрицательной."))
        .max(1000000000000)
        .typeError(t("Please fill in this field!"))
        .optional(),
    purchasePrice: yup.number().transform((value, original) => original === "" || original == null ? null : value).nullable().min(0).max(1000000000000).optional(),
    costPrice: yup.number().transform((value, original) => original === "" || original == null ? null : value).nullable().min(0).max(1000000000000).optional(),
    markupPercent: yup.number().transform((value, original) => original === "" || original == null ? null : value).nullable().min(0).max(1000000).optional(),
    categoryId: yup.string().required(t("Please fill in this field!")),
});
